def command_views(cmd):
    """The command as written, plus the form the shell will actually run.

    The raw text always comes first, so a failure in the folded view can only lose an added
    detection, never an existing one.
    """
    views = [("command", cmd)]
    try:
        folded = fold_empty(cmd)
        if folded != cmd:
            views.append(("command", folded))
    except Exception:
        pass
    return views

